p.fragment:
precision highp float; varying vec2 v_uv; uniform samplerCube u_env;
void main(){
  vec3 ro = vec3(0.0, 0.0, 3.0);
  vec3 rd = normalize(vec3(v_uv * 0.6, -1.0));
  vec3 c = textureCube(u_env, rd).rgb;
  float b = dot(ro, rd);
  float h = b*b - (dot(ro, ro) - 1.0);
  if (h > 0.0) {
    float t = -b - sqrt(h);
    vec3 p = ro + rd * t;
    vec3 n = normalize(p);
    vec3 r = reflect(rd, n);
    float fres = 0.15 + 0.85 * pow(1.0 - max(dot(-rd, n), 0.0), 3.0);
    c = mix(vec3(0.05), textureCube(u_env, r).rgb, 0.4 + 0.6 * fres);
  }
  gl_FragColor = vec4(c, 1.0);
}
